import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.item.Tier;
import net.minecraft.world.item.TooltipFlag;
import net.minecraft.world.level.Level;
import org.jetbrains.annotations.NotNull;
import yesman.epicfight.world.item.EpicFightItemTier;
import yesman.epicfight.world.item.WeaponItem;

public class TormentedMindItem
extends WeaponItem {
    private final float attackDamage;
    private final double attackSpeed;

    public TormentedMindItem(Item.Properties build) {
        super((Tier)EpicFightItemTier.UCHIGATANA, 0, -2.7f, build);
        this.attackDamage = 8.0f;
        this.attackSpeed = -2.7f;
    }

    public boolean m_6832_(@NotNull ItemStack toRepair, ItemStack repair) {
        return repair.m_41720_() == Items.f_42416_;
    }

    public void m_7373_(@NotNull ItemStack stack, @Nullable Level worldIn, List<Component> components, @NotNull TooltipFlag flagIn) {
        components.add((Component)Component.m_237113_((String)""));
        components.add((Component)Component.m_237115_((String)"item.wom.tormented_mind.tooltip"));
    }

    public Multimap<Attribute, AttributeModifier> getAttributeModifiers(EquipmentSlot slot, ItemStack stack) {
        if (slot == EquipmentSlot.MAINHAND) {
            ImmutableMultimap.Builder builder = ImmutableMultimap.builder();
            builder.put((Object)Attributes.f_22281_, (Object)new AttributeModifier(f_41374_, "Weapon modifier", (double)this.attackDamage, AttributeModifier.Operation.ADDITION));
            builder.put((Object)Attributes.f_22283_, (Object)new AttributeModifier(f_41375_, "Weapon modifier", this.attackSpeed, AttributeModifier.Operation.ADDITION));
            return builder.build();
        }
        return super.getAttributeModifiers(slot, stack);
    }
}

