import yesman.epicfight.world.capabilities.item.CapabilityItem;

public class GesetzCapability
extends CapabilityItem {
    protected GesetzCapability(CapabilityItem.Builder builder) {
        super(builder);
    }

    public UseAnim getUseAnimation(LivingEntityPatch<?> entitypatch) {
        return UseAnim.NONE;
    }

    public Map<LivingMotion, AnimationManager.AnimationAccessor<? extends StaticAnimation>> getLivingMotionModifier(LivingEntityPatch<?> playerdata, InteractionHand hand) {
        if (playerdata.getHoldingItemCapability(InteractionHand.MAIN_HAND) != null && playerdata.getHoldingItemCapability(InteractionHand.MAIN_HAND).getStyle(playerdata) == CapabilityItem.Styles.COMMON) {
            return ImmutableMap.of((Object)LivingMotions.BLOCK_SHIELD, AnimsHerrscher.HERRSCHER_MAHER_HOLD);
        }
        return ImmutableMap.of((Object)LivingMotions.BLOCK_SHIELD, AnimsHerrscher.HERRSCHER_GUARD);
    }
}

